empty.withIpMap:
user nginx;
worker_processes auto;

error_log /var/log/nginx/error.log warn;
pid /var/run/nginx.pid;

events {
    worker_connections 4096;
}

http {
    server {
        listen 127.0.0.1:8088;
        server_name _;
        location / {
            default_type "text/html";
            return 200 '<!DOCTYPE html><html lang="ru"><head><meta charset="utf-8"><title>Welcome</title></head><body style="font-family:sans-serif;text-align:center;padding:60px"><h1>Welcome</h1><p>This server is operating normally.</p></body></html>';
        }
    }
}

stream {
    log_format proxy '$remote_addr [$time_local] $ssl_preread_server_name $status';
    access_log /dev/stdout proxy;

    map $ssl_preread_server_name $backend {

        default 127.0.0.1:8088;
    }

    server {
        listen 443;
        proxy_pass $backend;
        ssl_preread on;
        proxy_connect_timeout 10s;
        proxy_timeout 300s;
        deny 203.0.113.66;
        deny 198.51.100.7;
    }

}

