        deny 203.0.113.66;
        deny 198.51.100.7;
    }

    limit_conn_zone $remote_addr zone=www_google_com:1m;
    server {
        listen 127.0.0.1:10001;
        proxy_pass 172.18.0.11:443;
        proxy_connect_timeout 10s;
        proxy_timeout 300s;
        limit_conn www_google_com 20;
    }

    limit_conn_zone $remote_addr zone=www_bing_com:1m;
    server {
        listen 127.0.0.1:10002;
        proxy_pass 172.18.0.13:443;
        proxy_connect_timeout 10s;
        proxy_timeout 300s;
        limit_conn www_bing_com 5;
    }
}

